import React, { useState } from "react";
import axios from "axios";

function RoleSelection({ user, logout }) {
  const [role, setRole] = useState(user.role || "");
  const [message, setMessage] = useState("");

  const roles = ["Students", "Professionals", "Homemakers", "Customize Role"];

  const handleRoleChange = async (selectedRole) => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.put(
        "http://localhost:5000/api/role",
        { role: selectedRole },
        { headers: { Authorization: token } }
      );
      setRole(res.data.user.role);
      setMessage("✅ Role updated successfully!");
    } catch (err) {
      setMessage("❌ Failed to update role.");
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gradient-to-r from-green-400 to-blue-500">
      <div className="bg-white p-8 rounded-3xl shadow-2xl w-96 text-center">
        <h2 className="text-3xl font-bold text-purple-700 mb-6">
          Welcome, {user.username}!
        </h2>

        <p className="mb-4 text-gray-700">Select your role:</p>

        <div className="flex flex-col gap-3">
          {roles.map((r) => (
            <button
              key={r}
              onClick={() => handleRoleChange(r)}
              className={`p-3 rounded-lg font-semibold transition-colors duration-300 ${
                role === r
                  ? "bg-purple-600 text-white"
                  : "bg-purple-200 text-purple-700 hover:bg-purple-400"
              }`}
            >
              {r}
            </button>
          ))}
        </div>

        {message && (
          <p className="mt-4 text-center font-medium">{message}</p>
        )}

        <button
          onClick={logout}
          className="mt-6 bg-red-500 text-white p-3 rounded-lg hover:bg-red-700 transition-colors duration-300"
        >
          Logout
        </button>
      </div>
    </div>
  );
}

export default RoleSelection;
